import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M15 1H1c-.55 0-1 .45-1 1v12c0 .55.45 1 1 1h14c.55 0 1-.45 1-1V2c0-.55-.45-1-1-1m1 4H0V3h16zm-3-2h-2V1h2z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M20 5v13a1 1 0 0 1-1 1H1a1 1 0 0 1-1-1V5zm-3-4h2a1 1 0 0 1 1 1v1h-3zm-2 2H0V2a1 1 0 0 1 1-1h14z"] as readonly string[];

export const ModalFilledIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="modal-filled" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
ModalFilledIcon.displayName = `Blueprint6.Icon.ModalFilledIcon`;

/**
 * @deprecated Use {@link ModalFilledIcon} instead.
 */
export const ModalFilled: typeof ModalFilledIcon = ModalFilledIcon;

export default ModalFilledIcon;
